def scoped(path):
    target = BASE / path
    need(not target.is_symlink() and target.resolve().is_relative_to(BASE.resolve()), 'graph_path_scope')
    return target

def read_pin(row):
    raw = scoped(row[0]).read_bytes()
    need((len(raw), digest(raw)) == row[1:], 'graph_actual_pin:' + row[0])
    return raw

def literal_assignment(raw, name):
    rows = [node for node in ast.parse(raw.decode('ascii')).body if isinstance(node, ast.Assign) and
            len(node.targets) == 1 and isinstance(node.targets[0], ast.Name) and node.targets[0].id == name]
    need(len(rows) == 1, 'single_literal:' + name)
    return ast.literal_eval(rows[0].value)

def replay(raw, edits, inverse=False):
    for row in reversed(edits) if inverse else edits:
        before, after = row['after' if inverse else 'before'].encode('ascii'), row['before' if inverse else 'after'].encode('ascii')
        need(raw.count(before) == row['count'], 'exact_edit_count:' + row['name'])
        raw = raw.replace(before, after)
    return raw

def definition_rows(raw):
    text = raw.decode('ascii')
    return tuple((type(node).__name__, node.name, node.lineno, node.end_lineno, ast.get_source_segment(text, node))
        for node in ast.walk(ast.parse(text, feature_version=(3, 5))) if isinstance(node, (ast.FunctionDef, ast.ClassDef)))

def validate_delta(before, after, edits, functions_unchanged=False):
    inverse = replay(after, edits, True)
    need(replay(before, edits) == after and inverse == before, 'complete_source_byte_inverse')
    need(ast.dump(ast.parse(inverse.decode('ascii')), include_attributes=True) ==
         ast.dump(ast.parse(before.decode('ascii')), include_attributes=True), 'complete_position_ast_inverse')
    old, new = definition_rows(before), definition_rows(after)
    need(tuple(row[:4] for row in old) == tuple(row[:4] for row in new) and
         len(before.splitlines()) == len(after.splitlines()), 'mechanical_definition_lines')
    if functions_unchanged:
        need(old == new, 'mechanical_all_definitions_byte_exact')

def validate_runner(raw, rows, private_rows, helpers, wpa, monitor):
    need(literal_assignment(raw, 'STATE_ROOT') == '/var/volatile/tmp/' + ROOT_AFTER and
         literal_assignment(raw, 'STATE_ALIAS') == '/tmp/' + ROOT_AFTER, 'runner_roots')
    need(literal_assignment(raw, 'ROLE_PINS') == tuple((n, size, sha) for n, p, size, sha in rows) and
         literal_assignment(raw, 'PRIVATE_PINS') == tuple((n[10:], size, sha) for n, p, size, sha in private_rows) and
         literal_assignment(raw, 'HELPER_PINS') == tuple((n, size, sha) for n, p, size, sha in helpers) and
         literal_assignment(raw, 'WPA_PIN') == (wpa[0], wpa[2], wpa[3]) and
         literal_assignment(raw, 'MONITOR_PIN') == (monitor[0], monitor[2], monitor[3]), 'runner_exact75_pins')

def _meta(value):
    return (value.st_dev, value.st_ino, value.st_mode, value.st_nlink,
            value.st_size, value.st_mtime_ns, value.st_ctime_ns)

def load_checker():
    # Only this literal bootstrap file is executed, never its __main__.
    for node in reversed((BASE,) + tuple(BASE.parents)):
        value = node.lstat()
        if (not stat.S_ISDIR(value.st_mode) or stat.S_ISLNK(value.st_mode) or
                getattr(value, 'st_file_attributes', 0) & 0x400):
            raise ValueError('checker_ancestor')
    path = BASE
    for part in CHECKER[0].split('/'):
        path = path / part
        value = path.lstat()
        if stat.S_ISLNK(value.st_mode) or getattr(value, 'st_file_attributes', 0) & 0x400:
            raise ValueError('checker_link')
        if path != BASE / CHECKER[0] and not stat.S_ISDIR(value.st_mode):
            raise ValueError('checker_ancestor')
    before = _meta(value)
    if not stat.S_ISREG(value.st_mode) or value.st_size != CHECKER[1]:
        raise ValueError('checker_file')
    with path.open('rb') as handle:
        opened = _meta(os.fstat(handle.fileno()))
        same = (opened[:2] == before[:2] and stat.S_IFMT(opened[2]) == stat.S_IFMT(before[2]) and
                opened[3:6] == before[3:6]) if os.name == 'nt' else opened == before
        if not same:
            raise ValueError('checker_identity')
        raw = handle.read(CHECKER[1] + 1)
        if _meta(os.fstat(handle.fileno())) != opened:
            raise ValueError('checker_changed')
    if _meta(path.lstat()) != before:
        raise ValueError('checker_changed')
    if (len(raw), digest(raw)) != CHECKER[1:]:
        raise ValueError('checker_pin')
    value = types.ModuleType('fixed_formal_receive_host_helpers')
    value.__file__ = str(path)
    exec(compile(raw, str(path), 'exec'), value.__dict__)
    if value.BASE != BASE:
        raise ValueError('checker_base')
    # Keep the bootstrap file/pin unchanged. Only this new private helper realm
    # has the exact new runner result schema; no old checker main is executed.
    value.BOOL_FIELDS = value.BOOL_FIELDS + ('interactive_window_requested',)
    value.FIELDS = frozenset(value.BOOL_FIELDS + value.COUNT_FIELDS + ('reason',))
    return value, raw

def _short_chunks(checker, raw):
    # Reuse the pinned helper's exact encoder, but not its 1024-character lines.
    # The device transport may traverse a canonical TTY with a 512-byte line cap.
    # Generated ASCII base64 repr is always this one quote shape, not arbitrary
    # input code. Fragment width96 keeps each physical encoded line below128.
    parts = []
    for line in checker.chunks(raw).splitlines():
        if (not line.startswith("    '") or not line.endswith("'") or
                re.fullmatch(r'[A-Za-z0-9+/=]{1,1024}', line[5:-1]) is None):
            raise ValueError('target_source_budget')
        parts.append(line[5:-1])
    encoded = ''.join(parts)
    if not encoded:
        raise ValueError('target_source_budget')
    return '\n'.join('    ' + repr(encoded[index:index + 96])
                     for index in range(0, len(encoded), 96))

def parse_trial_facts(raw):
    derived = raw.decode('utf-8', 'replace').replace('\r\r\n', '\n').replace('\r\n', '\n')
    output = {}
    for tag in ('START', 'END'):
        rows = re.findall(r'^TRIAL_' + tag + r'=(.*)$', derived, re.M)
        if len(rows) != 1:
            raise ValueError('remote_result_unknown')
        value = ast.literal_eval(rows[0])
        if (type(value) is not dict or set(value) != TRIAL_FIELDS or
                any(type(value[name]) is not bool for name in TRIAL_BOOL_FIELDS) or
                type(value['claim_count']) is not int or value['claim_count'] not in (0, 1) or
                type(value['reason']) is not str or value['reason'] not in TRIAL_REASONS):
            raise ValueError('result_fields')
        output[tag.lower()] = value
    return output

def manifest_rows(raw, private=False):
    value = json.loads(raw.decode('ascii'))
    original = json.loads((OLD_PRIVATE_RAW if private else ORIGINAL_MANIFEST_RAW).decode('ascii'))
    expected = PRIVATE_ROWS if private else ORDINARY_ROWS
    keys = {'schema', 'sources', 'previous_manifest_sha256'} if private else {'schema', 'sources'}
    need(type(value) is dict and set(value) == keys and value['schema'] == original['schema'] and
         type(value['sources']) is list and len(value['sources']) == 35 and
         (not private or value['previous_manifest_sha256'] == OLD_PRIVATE_MANIFEST[2]), 'progress_manifest_shape')
    rows = tuple(('runtime35/' + row['module'] if private else row['module'], row['path'], row['bytes'], row['sha256'])
                 for row in value['sources'])
    need(rows == expected, 'progress_manifest_exact_rows')
    return rows

def make_source(checker, inputs, payload, use_ui):
    if use_ui is not False:
        raise ValueError('compat_headless_only')
    modules = tuple(sorted(set(MODULE_NAMES + PRIVATE_MODULE_NAMES + (
        'fixed_formal_ui_session', 'fixed_formal_ui_runner', 'fixed_formal_ui_assets',
        'fixed_formal_receive_monitor', 'fixed_startup_readonly_diagnostic',
        'startup_readonly_private_owner', 'threading', 'socket', 'subprocess', 'types'))))
    lines = ['USE_UI=False', 'ERROR_MODULES=(']
    lines.extend('    ' + repr(name) + ',' for name in modules)
    lines.extend((')', 'RESULT_REASONS=('))
    lines.extend('    ' + repr(name) + ',' for name in
                 tuple(dict.fromkeys(tuple(checker.REASONS) + TRIAL_REASONS)))
    lines.append(')')
    lines.extend(('RUNNER_PIN=' + repr(RUNNER[1:]), 'RUNNER_ENCODED=(',
                  _short_chunks(checker, inputs[RUNNER[0]]), ')', 'ARTIFACT_ROWS=('))
    for name, path, size, sha in payload:
        lines.extend(('    (' + repr(name) + ',' + str(size) + ',' + repr(sha) + ',(',
                      _short_chunks(checker, inputs[path]), '    )),'))
    lines.append(')')
    raw = ('\n'.join(lines) + '\n' + TARGET_COMMON + TARGET_SERVICE).encode('ascii')
    if len(raw) > 2097152 or any(len(line) > 256 for line in raw.splitlines()):
        raise ValueError('target_source_budget')
    return raw

def owner_context(raw):
    text, tree = raw.decode('ascii'), ast.parse(raw.decode('ascii'), feature_version=(3, 5))
    classes = [node for node in tree.body if isinstance(node, ast.ClassDef) and node.name == 'FixedStateServiceOwner']
    need(len(classes) == 1, 'one_owner_class')
    methods = [node for node in classes[0].body if isinstance(node, ast.FunctionDef) and node.name == '_context']
    need(len(methods) == 1, 'one_owner_context')
    return ast.get_source_segment(text, methods[0])

def validate_owner_business(inputs, entry):
    before, seed = inputs[entry['source'][0]], inputs[entry['candidate'][0]]
    need((len(before), digest(before)) == tuple(entry['source'][1:]) and
         (len(seed), digest(seed)) == tuple(entry['candidate'][1:]), 'dispatch_business_pins')
    edits = entry['edits']
    need(len(edits) == 1 and edits[0]['count'] == 1 and edits[0]['name'] == 'owner_context_dispatch' and
         edits[0]['before'] == owner_context(before) and edits[0]['after'] == owner_context(seed),
         'only_owner_context_business_block')
    need(replay(before, edits) == seed and replay(seed, edits, True) == before and
         len(seed) - len(before) == 78, 'owner_dispatch_complete_byte_inverse')
    delta = json.loads(inputs[entry['seed_delta'][0]].decode('ascii'))
    need(delta == entry['seed_delta_expected'] and delta['origin'] == dict(
         path=entry['source'][0], bytes=entry['source'][1], sha256=entry['source'][2]) and
         delta['candidate'] == dict(path=entry['candidate'][0], bytes=entry['candidate'][1],
                                    sha256=entry['candidate'][2]), 'actual_seed_delta_bindings')
    partial = [dict(row, name='seed_dispatch') for row in delta['replacements']]
    need(len(partial) == 1 and partial[0]['count'] == 1 and replay(before, partial) == seed and
         replay(seed, partial, True) == before, 'actual_seed_partial_byte_inverse')
    restored = replay(seed, edits, True)
    need(ast.dump(ast.parse(restored), include_attributes=True) == ast.dump(ast.parse(before), include_attributes=True),
         'owner_dispatch_complete_position_ast_inverse')

def scope_originals(raw):
    text, tree = raw.decode('ascii'), ast.parse(raw.decode('ascii'), feature_version=(3, 5))
    classes = [node for node in tree.body if isinstance(node, ast.ClassDef) and node.name == '_StartupReadScope']
    need(len(classes) == 1, 'one_startup_scope_class')
    methods = [node for node in classes[0].body if isinstance(node, ast.FunctionDef) and node.name == '_originals']
    need(len(methods) == 1, 'one_startup_scope_originals')
    return ast.get_source_segment(text, methods[0])

def validate_scope_business(inputs, entry):
    before, seed = inputs[entry['source'][0]], inputs[entry['candidate'][0]]
    need((len(before), digest(before)) == tuple(entry['source'][1:]) and
         (len(seed), digest(seed)) == tuple(entry['candidate'][1:]), 'scope_business_pins')
    edits = entry['edits']
    need(len(edits) == 1 and edits[0]['count'] == 1 and edits[0]['name'] == 'scope_originals_dispatch' and
         edits[0]['before'] == scope_originals(before) and edits[0]['after'] == scope_originals(seed),
         'only_scope_originals_business_block')
    need(replay(before, edits) == seed and replay(seed, edits, True) == before and
         len(seed) - len(before) == 114, 'scope_dispatch_complete_byte_inverse')
    delta = json.loads(inputs[entry['seed_delta'][0]].decode('ascii'))
    need(delta == entry['seed_delta_expected'] and delta['schema'] ==
         'p011-receive-scope-dispatch-v1-exactsource-delta' and delta['origin'] == dict(
         path=entry['source'][0], bytes=entry['source'][1], sha256=entry['source'][2]) and
         delta['candidate'] == dict(path=entry['candidate'][0], bytes=entry['candidate'][1],
                                    sha256=entry['candidate'][2]), 'actual_scope_seed_delta_bindings')
    partial = [dict(row, name='scope_seed_dispatch') for row in delta['replacements']]
    need(len(partial) == 1 and partial[0]['count'] == 1 and replay(before, partial) == seed and
         replay(seed, partial, True) == before, 'actual_scope_seed_partial_byte_inverse')
    restored = replay(seed, edits, True)
    need(ast.dump(ast.parse(restored), include_attributes=True) == ast.dump(ast.parse(before), include_attributes=True),
         'scope_dispatch_complete_position_ast_inverse')

SOURCE_PINS = ORIGIN_SOURCE_PINS
FILECENTER_SOURCE_PINS = FILECENTER_SOURCES
TRIAL_FIELDS = frozenset(TRIAL_BOOL_FIELDS + ('claim_count', 'reason'))
json_bytes = jraw

def validate_fc_http_delta(inputs, entries):
    """Exactly one header clamp and one receive setup override; not runtime evidence."""
    need(type(entries) is list and len(entries) == 2 and
         tuple(row['name'] for row in entries) == FC_CHANGED, 'fc_two_actual_roles')
    for row in entries:
        before, after = inputs[row['source'][0]], inputs[row['candidate'][0]]
        need((len(before), digest(before)) == tuple(row['source'][1:]) and
             (len(after), digest(after)) == tuple(row['candidate'][1:]), 'fc_actual_source_pin')
        need(len(row['edits']) == 1 and row['edits'][0]['count'] == 1 and
             replay(before, row['edits']) == after and replay(after, row['edits'], True) == before,
             'fc_whole_source_forward_inverse')
        ast.parse(before.decode('utf-8'), feature_version=(3, 5))
        ast.parse(after.decode('utf-8'), feature_version=(3, 5))
        if row['name'] == 'mta_toolbox_minhttp':
            expected = dict(name='header_original_deadline_clamp',
                before='        header_deadline = time.monotonic()+4\n',
                after='        header_deadline = min(self.deadline, time.monotonic()+4)\n', count=1)
            need(row['edits'] == [expected] and len(after) - len(before) == 20, 'fc_header_only')
        else:
            expected = dict(name='receive_original_parent_cap_setup',
                before='class _FileCenterHandler(Handler):\n',
                after=('class _FileCenterHandler(Handler):\n'
                       '    def setup(self):\n'
                       '        self.deadline = min(self.deadline, self.server.companion.until)\n'
                       '        Handler.setup(self)\n\n'), count=1)
            need(row['edits'] == [expected] and len(after) - len(before) == 122, 'fc_receive_setup_only')

def verify_inputs(inputs):
    """The new definitions' independent validator, never called by prepare()."""
    for path, size, sha in ORIGIN_SOURCE_PINS:
        need(path in inputs and (len(inputs[path]), digest(inputs[path])) == (size, sha), 'fccap_flat_pin')
    need(inputs[OLD_MANIFEST[0]] == ORIGINAL_MANIFEST_RAW and
         inputs[OLD_PRIVATE_MANIFEST[0]] == OLD_PRIVATE_RAW, 'fccap_original_manifests')
    need(json.loads(inputs[DELTA_SPEC[0]].decode('ascii')) == DELTA_EXPECTED, 'fccap_exact_delta_metadata')
    # Retain and independently audit the already measured seed provenance.
    # These are copied pure inverse validators, not historical test methods.
    validate_owner_business(inputs, OWNER_BUSINESS_EXPECTED)
    validate_scope_business(inputs, BUSINESS_EXPECTED)
    validate_fc_http_delta(inputs, FC_HTTP_EXPECTED)
    for entry in MECHANICAL_EXPECTED:
        before, after = inputs[entry['source'][0]], inputs[entry['candidate'][0]]
        validate_delta(before, after, entry['edits'], entry['functions_unchanged'])
        need(len(before) == len(after), 'fccap_equal_length_mechanical_source')
    for entry in MANIFEST_EXPECTED:
        old = json.loads(inputs[entry['source'][0]].decode('ascii'))
        current = json.loads(inputs[entry['candidate'][0]].decode('ascii'))
        restored = copy.deepcopy(current)
        for index, before, after in entry['changes']:
            need(old['sources'][index] == before and current['sources'][index] == after, 'fccap_manifest_delta')
            restored['sources'][index] = before
        if entry['private']:
            restored['previous_manifest_sha256'] = old['previous_manifest_sha256']
        need(restored == old and jraw(current) == inputs[entry['candidate'][0]], 'fccap_manifest_inverse')
    payload = manifest_rows(inputs[MANIFEST[0]]) + HELPERS + manifest_rows(inputs[PRIVATE_MANIFEST[0]], True) + (WPA, MONITOR)
    need(len(payload) == 75 and len(set(row[0] for row in payload)) == 75, 'fccap75_unique')
    changed = []
    for row, before in zip(payload, ORIGINAL_PAYLOAD_ROWS):
        need(row[0] == before[0] and (len(inputs[row[1]]), digest(inputs[row[1]])) == row[2:], 'fccap75_actual')
        if row[0] in CHANGED_PAYLOAD_ROLES:
            need(row != before, 'fccap_changed_role')
            changed.append(row[0])
        else:
            need(row == before and inputs[row[1]] == inputs[before[1]], 'fccap69_original_roles')
    need(tuple(changed) == CHANGED_PAYLOAD_ROLES and sum(row[2] for row in payload) == PAYLOAD_BYTES == 4193464 <= 4194304,
         'fccap6_changed_payload_budget')
    validate_runner(inputs[RUNNER[0]], ORDINARY_ROWS, PRIVATE_ROWS, HELPERS, WPA, MONITOR)
    need(len(FILECENTER_SOURCE_PINS) == 9 and sum(row[2] for row in FILECENTER_SOURCE_PINS) == FILECENTER_BYTES == 113832 <= 131072,
         'fccap_separate_fc9_budget')
    expected_pins = tuple((name, size, sha) for name, path, size, sha in FILECENTER_SOURCE_PINS)
    owner_row = next(row for row in ORDINARY_ROWS if row[0] == 'mta_client_service_owner')
    need(literal_assignment(inputs[owner_row[1]], 'FILECENTER_PINS') == expected_pins, 'fccap_actual_owner_fc9')
    fc_changed = []
    for row, before in zip(FILECENTER_SOURCE_PINS, ORIGINAL_FILECENTER_ROWS):
        need(row[0] == before[0] and (len(inputs[row[1]]), digest(inputs[row[1]])) == row[2:], 'fccap_fc9_actual')
        if row[0] in FC_CHANGED:
            need(row != before, 'fccap_fc_changed_role')
            fc_changed.append(row[0])
        else:
            need(row == before and inputs[row[1]] == inputs[before[1]], 'fccap_fc7_unchanged')
    need(tuple(fc_changed) == FC_CHANGED, 'fccap_only_two_fc_sources')
    need(json.loads(inputs[GENERATION[0]].decode('ascii')) == GENERATION_EXPECTED, 'fccap_generation_exact')
    return MECHANICAL_CLOSURE_COUNT
